import xarray as xr
import numpy as np
from metpy.units import units
from metpy.xarray import MetPyDataArrayAccessor

def test_dbz_unit():
    try:
        # Create a dummy DataArray with units='dBZ'
        data = xr.DataArray(
            np.random.rand(10), 
            dims='x', 
            attrs={'units': 'dBZ'}
        )
        # This should trigger the UndefinedUnitError if dBZ is not defined
        quantified = data.metpy.quantify()
        print("Successfully quantified dBZ")
    except Exception as e:
        print(f"Caught expected error: {e}")
        raise e

if __name__ == "__main__":
    test_dbz_unit()

